#!/usr/bin/env bash
# Applies קמתי's customizations to the Android project generated by `npx cap add android`:
# icons, sounds, the Hebrew name, the alarm's own Java code (android-native/), permissions, signing.
set -euo pipefail

RUN="${GITHUB_RUN_NUMBER:-1}"
VERSION="${APP_VERSION:-1.0}"
APP=android/app
RES=$APP/src/main/res
MAN=$APP/src/main/AndroidManifest.xml

# 1) Icons, splash, the status-bar icon and the alarm sounds (res/raw/kamti_*.ogg)
find "$RES" -name 'splash.png' -delete
cp -R android-res/. "$RES/"

# 2) App name in Hebrew (the label under the icon)
STR=$RES/values/strings.xml
perl -0pi -e 's|<string name="app_name">[^<]*</string>|<string name="app_name">קמתי</string>|; s|<string name="title_activity_main">[^<]*</string>|<string name="title_activity_main">קמתי</string>|' "$STR"

# 3) The alarm: MainActivity (over the lock screen, keys locked, comes back) + plugin, service, receivers
MAIN=$(find "$APP/src/main/java" -name MainActivity.java | head -1)
DIR=$(dirname "$MAIN")
PKG=$(sed -n 's/^package \(.*\);/\1/p' "$MAIN")
[ "$PKG" = "com.luachsport.kamti" ] || { echo "unexpected package $PKG"; exit 1; }
cp android-native/*.java "$DIR/"

perl -0pi -e 's|</application>|        <receiver android:name=".AlarmReceiver" android:exported="false" />\n        <receiver android:name=".BootReceiver" android:exported="true">\n            <intent-filter>\n                <action android:name="android.intent.action.BOOT_COMPLETED" />\n                <action android:name="android.intent.action.QUICKBOOT_POWERON" />\n                <action android:name="android.intent.action.MY_PACKAGE_REPLACED" />\n                <action android:name="android.intent.action.TIME_SET" />\n                <action android:name="android.intent.action.TIMEZONE_CHANGED" />\n                <action android:name="android.app.action.SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED" />\n            </intent-filter>\n        </receiver>\n        <service android:name=".AlarmService" android:exported="false" android:foregroundServiceType="mediaPlayback" />\n    </application>|' "$MAN"

PERMS='    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />
    <uses-permission android:name="android.permission.VIBRATE" />
    <uses-permission android:name="android.permission.WAKE_LOCK" />
    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />
    <uses-permission android:name="android.permission.USE_EXACT_ALARM" />
    <uses-permission android:name="android.permission.SCHEDULE_EXACT_ALARM" android:maxSdkVersion="32" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK" />
    <uses-permission android:name="android.permission.USE_FULL_SCREEN_INTENT" />
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />
    <uses-permission android:name="android.permission.SYSTEM_ALERT_WINDOW" />
    <uses-permission android:name="android.permission.REQUEST_IGNORE_BATTERY_OPTIMIZATIONS" />
    <uses-permission android:name="android.permission.CAMERA" />
    <uses-feature android:name="android.hardware.camera" android:required="false" />
    <uses-feature android:name="android.hardware.camera.autofocus" android:required="false" />
    <uses-feature android:name="android.hardware.sensor.accelerometer" android:required="false" />
    <uses-feature android:name="android.hardware.touchscreen" android:required="false" />'
PERMS="$PERMS" perl -0pi -e 's|</manifest>|$ENV{PERMS}\n</manifest>|' "$MAN"

# 4) Violet splash with the sunrise on Android 12+
STY=$RES/values/styles.xml
perl -0pi -e 's|(<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">)|$1\n        <item name="windowSplashScreenBackground">#5B3DF5</item>\n        <item name="windowSplashScreenAnimatedIcon">\@mipmap/ic_launcher_foreground</item>|' "$STY"

# 5) Target SDK 34 (the app is installed directly, not from Play)
sed -i -E 's/targetSdkVersion = [0-9]+/targetSdkVersion = 34/' android/variables.gradle

# 6) Version: name is the product version, code is the build number (so every APK installs as an update)
sed -i -E "s/versionCode [0-9]+/versionCode ${RUN}/; s/versionName \"[^\"]*\"/versionName \"${VERSION}\"/" "$APP/build.gradle"

# 7) Release signing with the permanent key (password from GitHub secrets)
cat >> "$APP/build.gradle" <<'GRADLE'

android {
    signingConfigs {
        kamti {
            storeFile file("release.jks")
            storePassword System.getenv("KAMTI_STORE_PASSWORD")
            keyAlias System.getenv("KAMTI_KEY_ALIAS")
            keyPassword System.getenv("KAMTI_KEY_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.kamti
            minifyEnabled false
        }
    }
}
GRADLE

echo "--- manifest"; grep -n 'permission\|receiver\|service\|feature\|launchMode' "$MAN"
echo "--- strings"; cat "$STR"
echo "--- java ($PKG)"; ls "$DIR"
echo "--- raw"; ls "$RES/raw"
echo "--- launch style"; grep -n -A3 'NoActionBarLaunch' "$STY"
echo "--- versions"; grep -n -E 'versionCode|versionName' "$APP/build.gradle"; grep -n -E 'targetSdk|minSdk' android/variables.gradle
